import json,requests,sys,io
from urllib.parse import urlparse
import time
rows=json.load(open('/tmp/final_rows.json','r',encoding='utf-8'))
out=[]
count=0
for r in rows:
    href=r.get('href')
    if not href: continue
    try:
        print('Fetching',href)
        resp=requests.get(href,timeout=20)
        html=resp.text
        start=html.find('<script id="__NEXT_DATA__"')
        if start==-1:
            # fallback: search for window.__FIS_WEB_DATA_URL
            print('no next data')
            continue
        start=html.find('>',start)+1
        end=html.find('</script>',start)
        jtxt=html[start:end]
        data=json.loads(jtxt)
        # Search for any 'results' arrays
        def find_results(obj):
            if isinstance(obj,dict):
                for k,v in obj.items():
                    if k.lower()=='results' and isinstance(v,list) and v:
                        return v
                for v in obj.values():
                    res=find_results(v)
                    if res: return res
            elif isinstance(obj,list):
                for item in obj:
                    res=find_results(item)
                    if res: return res
            return None
        results=find_results(data)
        titlestart=html.find('<title>')
        titleend=html.find('</title>',titlestart)
        title=html[titlestart+7:titleend].strip() if titlestart!=-1 else ''
        # heuristic: skip if title contains 'Qualification' or 'Qualification' in html
        if 'Qualification' in html or 'Qualification' in title or 'Qual' in title:
            print('skip qualification')
            continue
        # find result table rows in html as fallback: look for competitor names using pattern 'athlete-name' or 'link-to-competitor'
        # but try to find top3 from results list objects
        top3=[]
        gu_pos=None
        if results:
            # results elements may have 'rank' and 'competitor' with 'name'
            for item in results:
                # item could be dict with athlete
                name=None
                rank=None
                if isinstance(item,dict):
                    # try lots of keys
                    if 'position' in item: rank=item.get('position')
                    if 'rank' in item: rank=item.get('rank')
                    # competitor
                    comp=None
                    for k in ['competitor','athlete','athleteProfile','result']:
                        if k in item and isinstance(item[k],dict):
                            comp=item[k]
                            break
                    if comp:
                        name=comp.get('name') or comp.get('fullName') or comp.get('displayName')
                    # or item might have 'athleteName'
                    if not name:
                        for key in ['name','athleteName','personName','displayName','fullName']:
                            if key in item:
                                name=item[key]
                                break
                if name and rank:
                    try:
                        rank_i=int(rank)
                    except:
                        rank_i=None
                    if rank_i and rank_i<=3:
                        top3.append((rank_i,name))
                    # check if name contains Gu
                    if name and 'Gu' in name and gu_pos is None:
                        gu_pos=rank
            top3_sorted=[n for _,n in sorted(top3, key=lambda x:x[0])]
        # fallback: parse HTML podium area
        if not top3_sorted:
            import re
            m=re.search(r'Podium[\s\S]{0,400}?class="result-list"[\s\S]*?<ul>([\s\S]*?)</ul>',html)
            if m:
                lis=re.findall(r'<li[^>]*>\s*<span[^>]*>([^<]+)</span>',m.group(1))
                if lis:
                    top3_sorted=lis
        # if still empty, try to find first three occurrences of competitor links in table
        if not top3_sorted:
            import re
            names=re.findall(r'<a[^>]+href="/DB/general/athlete.html[^"]+">\s*([^<]+)\s*</a>',html)
            if names:
                top3_sorted=names[:3]
        # prepare discipline from title
        discipline=''
        for d in ['Big Air','Slopestyle','Halfpipe','Superpipe']:
            if d.lower() in title.lower(): discipline=d
        level=''
        for L in ['World Cup','World Championships','World Championship','Olympic','Youth Olympic','X Games']:
            if L.lower() in title.lower(): level=L
        # final row
        result_text=''
        if r['result'].isdigit():
            pos=int(r['result'])
            if pos==1: result_text='Gold'
            elif pos==2: result_text='Silver'
            elif pos==3: result_text='Bronze'
            else: result_text=str(pos)
        else:
            result_text=r['result']
        row={'date':r['date'],'event':title or r['event'],'level':level or r['level'],'discipline':discipline or r['discipline'],'result':result_text,'top3':'; '.join(top3_sorted) if top3_sorted else ''}
        out.append(row)
        count+=1
        if count>=58:
            break
        time.sleep(0.3)
    except Exception as e:
        print('error',e)
        continue
print('got',len(out))
json.dump(out, open('/tmp/compiled_rows.json','w',encoding='utf-8'),ensure_ascii=False,indent=2)
